('62239c0a-129e-4bd8-969e-7744bac15bac',	'BOOKING_INVOICE',	'Booking Invoice',	'Full client-facing booking invoice with passenger list, itemized services and financial totals.',	'<!DOCTYPE html> 
<html lang="en"> 
<head> 
<meta charset="UTF-8" /> 
<title>Booking Invoice Template</title> 
<style> 
@import url(''https://fonts.googleapis.com/css2?family=Outfit:wght@400;600;700;900&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap''); 

@media print { 
    body { 
        background: #FFFFFF !important; 
        color: #000000 !important; 
        -webkit-print-color-adjust: exact !important; 
        print-color-adjust: exact !important; 
    } 
    .no-print { 
        display: none !important; 
    } 
    .page-break { 
        page-break-before: always; 
    } 
} 

* { 
    box-sizing: border-box; 
} 

body { 
    font-family: ''Plus Jakarta Sans'', sans-serif; 
    color: #1E293B; 
    background: #F8FAFC; 
    margin: 0; 
    padding: 20px; 
    font-size: 11px; 
    line-height: 1.5; 
} 

.document-container { 
    max-width: 800px; 
    margin: 0 auto; 
    background: #FFFFFF; 
    border: 1px solid #E2E8F0; 
    border-radius: 12px; 
    padding: 30px; 
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05); 
} 

/* Header grid */ 
.doc-header { 
    display: flex; 
    justify-content: space-between; 
    align-items: flex-start; 
    border-bottom: 2px solid #F1F5F9; 
    padding-bottom: 20px; 
    margin-bottom: 24px; 
} 

.brand-block { 
    display: flex; 
    flex-direction: column; 
    gap: 4px; 
} 

.logos-block { 
    display: flex; 
    gap: 8px; 
    align-items: center; 
} 

/* Title & Reference */ 
.doc-title-section { 
    display: flex; 
    justify-content: space-between; 
    margin-bottom: 20px; 
} 

.doc-title { 
    font-family: ''Outfit'', sans-serif; 
    font-size: 20px; 
    font-weight: 900; 
    color: #0F172A; 
    text-transform: uppercase; 
    margin: 0; 
} 

.doc-meta { 
    text-align: right; 
} 

.doc-meta p { 
    margin: 2px 0; 
    color: #475569; 
} 

.doc-meta strong { 
    color: #0F172A; 
} 

/* Customer/Vendor Blocks */ 
.info-grid { 
    display: grid; 
    grid-template-cols: 1fr 1fr; 
    gap: 20px; 
    margin-bottom: 24px; 
    background: #F8FAFC; 
    padding: 16px; 
    border-radius: 8px; 
    border: 1px solid #F1F5F9; 
} 

.info-box h3 { 
    font-family: ''Outfit'', sans-serif; 
    font-size: 11px; 
    text-transform: uppercase; 
    color: #0EA5E9; 
    margin-top: 0; 
    margin-bottom: 8px; 
    letter-spacing: 1px; 
    font-weight: 700; 
} 

.info-box p { 
    margin: 3px 0; 
    color: #334155; 
} 

/* Detail Tables */ 
table.data-table { 
    width: 100%; 
    border-collapse: collapse; 
    margin-bottom: 24px; 
} 

table.data-table th { 
    background: #0F172A; 
    color: #FFFFFF; 
    font-family: ''Outfit'', sans-serif; 
    font-weight: 700; 
    text-transform: uppercase; 
    font-size: 9px; 
    letter-spacing: 0.5px; 
    padding: 8px 12px; 
    text-align: left; 
    border: 1px solid #0F172A; 
} 

table.data-table td { 
    padding: 8px 12px; 
    border: 1px solid #E2E8F0; 
    vertical-align: top; 
} 

table.data-table tr:nth-child(even) { 
    background: #F8FAFC; 
} 

.text-right { 
    text-align: right !important; 
} 

.text-center { 
    text-align: center !important; 
} 

/* Financial Breakdown Panel */ 
.financial-panel { 
    display: flex; 
    justify-content: flex-end; 
    margin-top: 20px; 
    margin-bottom: 24px; 
} 

.financial-table { 
    width: 300px; 
    border-collapse: collapse; 
} 

.financial-table td { 
    padding: 6px 12px; 
    border-bottom: 1px solid #E2E8F0; 
} 

.financial-table tr.total-row td { 
    font-size: 13px; 
    font-weight: 700; 
    color: #0F172A; 
    border-bottom: 2px double #0F172A; 
    background: #F8FAFC; 
} 

.financial-table tr.due-row td { 
    font-size: 14px; 
    font-weight: 900; 
    color: #E11D48; 
    background: #FFF1F2; 
    border: 1px solid #FFE4E6; 
} 

/* Signature Section */
.signature-section {
    display: flex;
    justify-content: space-between;
    margin-top: 40px;
    margin-bottom: 20px;
    padding: 0 20px;
}

.signature-box {
    width: 40%;
    text-align: left;
}

.signature-line {
    border-bottom: 1px solid #0F172A;
    height: 40px;
    margin-bottom: 8px;
}

.signature-text {
    font-family: ''Outfit'', sans-serif;
    font-weight: 700;
    font-size: 10px;
    color: #0F172A;
    text-transform: uppercase;
    margin: 0;
}

/* Footer Details */ 
.doc-footer { 
    border-top: 2px dashed #E2E8F0; 
    padding-top: 20px; 
    margin-top: 10px; 
    text-align: center; 
    color: #64748B; 
    font-size: 9px; 
} 

.doc-footer p { 
    margin: 4px 0; 
} 

/* Section Title badge style */ 
.section-badge { 
    display: inline-block; 
    padding: 2px 6px; 
    background: #E0F2FE; 
    color: #0369A1; 
    font-weight: 700; 
    border-radius: 4px; 
    font-size: 8px; 
    text-transform: uppercase; 
    letter-spacing: 0.5px; 
    margin-bottom: 10px; 
} 

/* E-ticket / Voucher Specifics */ 
.ticket-card { 
    border: 1.5px solid #0F172A; 
    border-radius: 8px; 
    overflow: hidden; 
    margin-bottom: 20px; 
} 

/* Timeline component styles */ 
.timeline-container { 
    position: relative; 
    padding-left: 28px; 
    margin: 20px 0 20px 8px; 
    border-left: 2px solid #E2E8F0; 
} 

.timeline-item { 
    position: relative; 
    margin-bottom: 20px; 
} 

.timeline-item:last-child { 
    margin-bottom: 0; 
} 

.timeline-badge { 
    position: absolute; 
    left: -40px; 
    top: 2px; 
    width: 22px; 
    height: 22px; 
    border-radius: 50%; 
    background: #FFFFFF; 
    border: 2px solid #64748B; 
    display: flex; 
    align-items: center; 
    justify-content: center; 
    font-size: 10px; 
    z-index: 10; 
} 

.timeline-badge.flight { 
    border-color: #0284C7; 
    color: #0284C7; 
} 

.timeline-badge.hotel { 
    border-color: #10B981; 
    color: #10B981; 
} 

.timeline-badge.transfer { 
    border-color: #F59E0B; 
    color: #F59E0B; 
} 

.timeline-badge.visa { 
    border-color: #8B5CF6; 
    color: #8B5CF6; 
} 

.timeline-badge.special { 
    border-color: #EC4899; 
    color: #EC4899; 
} 

.timeline-card { 
    background: #F8FAFC; 
    border: 1px solid #E2E8F0; 
    border-radius: 8px; 
    padding: 12px 16px; 
    text-align: left; 
} 

.timeline-card-header { 
    display: flex; 
    justify-content: space-between; 
    align-items: center; 
    margin-bottom: 8px; 
    border-bottom: 1px dashed #E2E8F0; 
    padding-bottom: 6px; 
} 

.timeline-title { 
    font-family: ''Outfit'', sans-serif; 
    font-size: 12px; 
    font-weight: 700; 
    color: #0F172A; 
} 

.timeline-date { 
    font-size: 9.5px; 
    color: #64748B; 
    font-weight: 600; 
} 

.timeline-grid { 
    display: grid; 
    grid-template-columns: repeat(2, 1fr); 
    gap: 8px 16px; 
    font-size: 10px; 
} 

.timeline-detail-item { 
    color: #475569; 
} 

.timeline-detail-item strong { 
    color: #0F172A; 
} 

.timeline-badge-status { 
    font-size: 8px; 
    font-weight: 800; 
    padding: 1px 6px; 
    border-radius: 99px; 
    text-transform: uppercase; 
} 

.timeline-badge-status.confirmed { 
    background: #DCFCE7; 
    color: #15803D; 
} 

.timeline-badge-status.pending { 
    background: #FEF3C7; 
    color: #D97706; 
} 

.timeline-badge-status.cancelled { 
    background: #FEE2E2; 
    color: #991B1B; 
} 

/* Terms Grid styling */ 
.terms-grid { 
    display: grid; 
    grid-template-columns: 1fr 1fr; 
    gap: 16px; 
    margin-top: 24px; 
    font-size: 8.5px; 
    color: #64748B; 
    text-align: left; 
} 

.terms-card { 
    background: #F8FAFC; 
    border: 1px solid #E2E8F0; 
    border-radius: 8px; 
    padding: 12px; 
} 

.terms-card h4 { 
    margin: 0 0 6px 0; 
    color: #0F172A; 
